def algorithm(func, dim, lb, ub, budget, rng):
    def grad(x):
        return 2 * x

    def get_candidate(rng):
        candidate = (ub - lb) * rng + lb
        return np.clip(candidate, lb, ub)

    best_x = np.zeros(dim)
    best_f = float('inf')

    for _ in range(budget):
        x = get_candidate(rng)

        f = func(x)
        g = grad(x)

        if f < best_f:
            best_f = f
            best_x = x

        step_size = 0.1
        for i in range(dim):
            candidate1 = x - step_size * g[i]
            candidate2 = x + step_size * g[i]

            candidate1 = np.clip(candidate1, lb, ub)
            candidate2 = np.clip(candidate2, lb, ub)

            f1 = func(candidate1)
            f2 = func(candidate2)

            if f1 < best_f:
                best_f = f1
                best_x = candidate1
            elif f2 < best_f:
                best_f = f2
                best_x = candidate2

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def generate_candidate(x, sigma):
        candidate = x + np.random.normal(size=dim, loc=0, scale=sigma)
        return clip(candidate)

    x_best = np.zeros(dim)
    f_best = func(x_best)

    for i in range(budget):
        lambda_ = 10. / (i + 1) ** 0.9
        sigma = (ub - lb) * rng.uniform(0, 1)

        population_size = int(lambda_ * dim)
        x_population = np.array([generate_candidate(x_best, sigma) for _ in range(population_size)])

        f_values = func(x_population)

        idxs = np.argsort(f_values)[:int(population_size/2)]
        x_population = x_population[idxs]

        if i % 10 == 0:
            print('Iteration {}: {:.4f}'.format(i, f_best))

        for j in range(population_size):
            candidate = generate_candidate(x_population[j], sigma)
            f_value = func(candidate)

            if f_value < f_best:
                x_best = candidate
                f_best = f_value

    return x_best

